INSERT INTO `b_thing` VALUES (1, 'iPhone 15 Pro 256GB 钛金属', '8bd77954-f4f3-40c1-8618-dd0ff0acd5e1.png', 'iPhone 15 Pro采用钛金属设计，搭载A17 Pro芯片，支持空间视频和空间音频，配备4800万像素主摄，支持USB-C接口，续航能力强大，是苹果最新旗舰手机。', '7999', '0', '1775875103280', '500', '0', '0', NULL, '0', '1', 1);
INSERT INTO `b_thing` VALUES (2, '华为Mate 60 Pro 512GB 曜金黑', '84955540-268e-442c-8907-61acb9614435.jpeg', '华为Mate 60 Pro采用昆仑玻璃，搭载麒麟9000S芯片，支持卫星通信，配备5000万像素超感知摄像头，支持66W超级快充，是华为最新旗舰手机。', '6999', '0', '1775875103280', '300', '0', '0', NULL, '0', NULL, 1);
INSERT INTO `b_thing` VALUES (3, '三星Galaxy S24 Ultra 512GB 星河黑', '6ff5f986-d583-43c9-986f-782ff6c5ba75.jpeg', '三星Galaxy S24 Ultra采用钛金属边框，搭载骁龙8 Gen 3处理器，配备2亿像素主摄，支持S Pen触控笔，搭载Galaxy AI人工智能系统，是三星最新旗舰手机。', '8999', '0', '1775875103280', '200', '0', '0', NULL, '0', NULL, 1);
INSERT INTO `b_thing` VALUES (4, '联想小新Pro 16 2024款 i7/16GB/512GB', 'a3d58ef9-9cbc-4376-af07-61bca2359bf1.jpeg', '联想小新Pro 16 2024款搭载第13代英特尔酷睿i7处理器，16GB内存，512GB固态硬盘，16英寸2.5K高清屏幕，支持WiFi 6，轻薄便携，是学生和办公人士的理想选择。', '5999', '0', '1775875103280', '150', '0', '0', NULL, '0', NULL, 2);
INSERT INTO `b_thing` VALUES (5, '戴尔XPS 13 Plus i7/16GB/1TB', '63fd5eef-a1b1-42e1-a39f-8eb0b43a3fa5.jpeg', '戴尔XPS 13 Plus采用全新设计，搭载第13代英特尔酷睿i7处理器，16GB内存，1TB固态硬盘，13.4英寸4K触控屏，支持雷电4接口，轻至1.24kg，是商务人士的理想选择。', '10999', '0', '1775875103280', '100', '0', '0', NULL, '0', NULL, 2);
INSERT INTO `b_thing` VALUES (6, '美的智能变频空调 1.5匹 冷暖', 'a1a4c63a-b034-441f-9655-500ac64b0262.jpeg', '美的智能变频空调采用全直流变频技术，支持WiFi智能控制，APF能效等级一级，静音设计，快速制冷制热，自清洁功能，是家庭理想的空调选择。', '2499', '0', '1775875103280', '200', '0', '0', NULL, '0', NULL, 3);
INSERT INTO `b_thing` VALUES (7, '海尔滚筒洗衣机 10KG 洗烘一体', '59b74023-1c86-4ae0-bc7a-e4d826385878.jpeg', '海尔滚筒洗衣机采用直驱变频技术，支持洗烘一体，10KG大容量，智能投放，蒸汽除菌，静音设计，支持APP远程控制，是现代家庭的理想选择。', '3999', '0', '1775875103280', '150', '0', '0', NULL, '0', NULL, 3);
INSERT INTO `b_thing` VALUES (8, '耐克Air Jordan 1 高帮篮球鞋', '93955ae4-4c0e-4b54-9811-512a31ab96fc.jpeg', '耐克Air Jordan 1 高帮篮球鞋采用经典设计，优质皮革鞋面，Air气垫缓震，橡胶外底提供出色抓地力，是篮球爱好者和潮流人士的必备选择。', '1299', '0', '1775875103280', '300', '0', '0', NULL, '0', NULL, 4);
INSERT INTO `b_thing` VALUES (9, '阿迪达斯三叶草经典休闲外套', '3fe3d547-98f1-40af-b7bf-a80630a144bb.jpeg', '阿迪达斯三叶草经典休闲外套采用优质面料，经典三条纹设计，舒适贴合，多口袋设计，适合日常穿着和运动场合，是休闲时尚的理想选择。', '899', '0', '1775875103280', '200', '0', '0', NULL, '0', NULL, 4);
INSERT INTO `b_thing` VALUES (10, '兰蔻小黑瓶精华肌底液 100ml', '7401f99d-6ea2-4670-89a4-a91753135de9.jpeg', '兰蔻小黑瓶精华肌底液含有7种益生菌提取物，能够强化肌肤屏障，提升肌肤光泽度，改善肤质，适合各种肤质，是护肤的必备选择。', '1050', '0', '1775875103280', '100', '0', '0', NULL, '0', NULL, 5);
INSERT INTO `b_thing` VALUES (11, '雅诗兰黛双棕瓶特润修护精华露 50ml', '351c0419-a3da-4d13-8380-9e01df413e1d.png', '雅诗兰黛双棕瓶特润修护精华露含有ChronoluxCB修护科技，能够修护肌肤，提升弹性，减少细纹，适合各种肤质，是抗老化护肤的理想选择。', '880', '0', '1775875103280', '80', '0', '0', NULL, '0', NULL, 5);
INSERT INTO `b_thing` VALUES (12, '无印良品风格简约沙发 三人座', 'd6e0d0e0-774c-49c3-9ca0-8ed7818c1779.jpeg', '无印良品风格简约沙发采用优质亚麻面料，实木框架，高弹性海绵填充，舒适耐用，简约设计适合各种家居风格，是客厅的理想选择。', '2999', '0', '1775875103280', '50', '0', '0', NULL, '0', NULL, 6);
INSERT INTO `b_thing` VALUES (13, '北欧风格实木餐桌椅组合 一桌四椅', '61bdbc8d-8afc-43c0-bc42-b5acf821c20c.jpeg', '北欧风格实木餐桌椅组合采用优质白橡木材质，环保漆面，简约设计，耐用稳固，适合各种家居风格，是餐厅的理想选择。', '3499', '0', '1775875103280', '30', '0', '0', NULL, '0', NULL, 6);
INSERT INTO `b_thing` VALUES (14, '五常有机稻花香大米 5kg', '7b1c0291-65a2-49ab-a2c9-f314173f7f44.jpeg', '五常有机稻花香大米产自黑龙江五常，采用有机种植方式，不使用化肥农药，口感软糯香甜，营养丰富，是家庭日常食用的理想选择。', '99', '0', '1775875103280', '500', '0', '0', NULL, '0', NULL, 7);
INSERT INTO `b_thing` VALUES (15, '新西兰进口牛排套餐 10片装', 'ff093047-bb02-4502-97d4-896c13bf6005.jpeg', '新西兰进口牛排套餐包含西冷、眼肉、菲力等多种部位，草饲牛肉，肉质鲜嫩多汁，富含蛋白质，是牛排爱好者的理想选择。', '299', '0', '1775875103280', '100', '0', '0', NULL, '0', NULL, 7);
INSERT INTO `b_thing` VALUES (16, '特步专业跑步鞋 轻量缓震', 'be6374f6-07e5-448d-b4ff-4c69efad2d92.jpeg', '特步专业跑步鞋采用轻量化设计，动态缓震技术，透气网面，防滑橡胶外底，适合日常跑步和健身，是运动爱好者的理想选择。', '299', '0', '1775875103280', '200', '0', '0', NULL, '0', NULL, 8);
INSERT INTO `b_thing` VALUES (17, '探路者户外登山包 40L', '11f4cde3-1306-4cea-a20e-4ded1d9cba15.jpeg', '探路者户外登山包采用耐磨尼龙材质，人体工学背负系统，多口袋设计，防泼水处理，适合户外登山和旅行，是户外爱好者的理想选择。', '399', '0', '1775875103280', '150', '0', '0', NULL, '0', NULL, 8);
INSERT INTO `b_thing` VALUES (18, '贝亲奶瓶套装 宽口径 玻璃', '437e2eb1-6bb2-4da1-b20b-afec444e416e.jpeg', '贝亲奶瓶套装采用高硼硅玻璃材质，耐高温，宽口径设计，仿真乳感奶嘴，防胀气系统，易清洁，是婴儿喂养的理想选择。', '199', '0', '1775875103280', '100', '0', '0', NULL, '0', '1', 9);
INSERT INTO `b_thing` VALUES (19, '费雪益智早教玩具套装', '5e037052-75cd-458f-8531-a657c91e5f5c.jpeg', '费雪益智早教玩具套装包含多种感官刺激玩具，有助于宝宝视觉、听觉、触觉发展，安全无毒材质，适合0-3岁宝宝，是早期教育的理想选择。', '299', '0', '1775875103280', '80', '0', '0', NULL, '0', '1', 9);
INSERT INTO `b_thing` VALUES (20, '计算机网络教程(第4版)', 'bee32979-f489-456b-a0f8-485e4984ef11.jpeg', '《计算机网络教程》第4版由著名网络专家编写，全面介绍计算机网络基础知识和最新技术，包含大量实例和习题，适合计算机专业学生和IT从业人员学习参考。', '77', '0', '1775875103280', '200', '0', '0', NULL, '0', '1', 10);
INSERT INTO `b_thing` VALUES (21, '算法精粹：经典计算机科学问题的Python实现', '5fd4f671-1744-49c3-b860-46cdcf72ee21.jpeg', '《算法精粹》通过Python语言实现经典算法，包括排序、搜索、图论、动态规划等，代码简洁易懂，配有详细解释和图示，适合编程爱好者和计算机专业学生。', '55', '0', '1775875103280', '150', '0', '0', NULL, '0', NULL, 10);
