-- ----------------------------
-- Table structure for b_ai_product_profile
-- ----------------------------
DROP TABLE IF EXISTS `b_ai_product_profile`;
CREATE TABLE `b_ai_product_profile`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `thing_id` bigint NOT NULL COMMENT '商品ID，对应 b_thing.id',
  `profile_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'AI 生成的完整结构化档案 JSON',
  `search_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '导购召回使用的合并检索文本',
  `keywords` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关键词，逗号分隔',
  `scenes` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '适用场景，逗号分隔',
  `target_users` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '目标人群，逗号分隔',
  `selling_points` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '核心卖点，逗号分隔',
  `specs` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '规格参数 JSON',
  `image_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '图片/封面识别摘要',
  `content_quality_score` int NULL DEFAULT 0 COMMENT '商品资料完整度评分 0-100',
  `source_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品基础信息指纹',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'READY' COMMENT 'READY/FALLBACK/FAILED',
  `error_message` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生成异常信息',
  `generated_at` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生成时间戳',
  `create_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建时间戳',
  `update_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新时间戳',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ai_product_profile_thing_id`(`thing_id` ASC) USING BTREE,
  INDEX `idx_ai_product_profile_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品 AI 导购档案表' ROW_FORMAT = Dynamic;

